import { useState } from "react";
import { Reveal, SectionHeader } from "./Reveal";

const foundationStacks = [
  {
    category: "Web",
    items: ["TypeScript", "React", "Tailwind CSS"],
  },
  {
    category: "Backend",
    items: ["Java", "C#", "PHP / Laravel", "Python"],
  },
  {
    category: "Data",
    items: ["SQLite", "PostgreSQL (RLS)", "Supabase"],
  },
  {
    category: "Systems",
    items: ["Offline-First", "REST APIs", "OAuth 2.0"],
  },
];

export function Skills() {
  const [spotlightPos, setSpotlightPos] = useState({ x: 0, y: 0, opacity: 0 });

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setSpotlightPos({
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
      opacity: 1,
    });
  };

  const handleMouseLeave = () => {
    setSpotlightPos((prev) => ({ ...prev, opacity: 0 }));
  };

  return (
    <section id="skills" className="relative py-12 md:py-24 bg-surface/30">
      <div className="relative z-10 mx-auto max-w-7xl px-5 sm:px-6">
        <SectionHeader
          index="03"
          label="Frontier Tooling"
          title={
            <>
              Production foundations,{" "}
              <span className="sm:inline-block sm:whitespace-nowrap">
                accelerated at the frontier.
              </span>
            </>
          }
          titleClassName="max-w-none text-2xl sm:text-3xl md:text-4xl lg:text-[2.65rem] xl:text-[3.25rem] lg:whitespace-nowrap leading-tight"
        />

        {/* Foundation Horizon Datum — 2x2 Grid */}
        <Reveal delay={0.1}>
          <div className="mb-3.5 rounded-xl border border-white/[0.08] bg-[#0c0c0f]/80 p-3 sm:p-4 select-none backdrop-blur-md">
            <div className="flex items-center justify-between pb-2 mb-2.5 border-b border-white/[0.05] font-mono text-[10px] text-zinc-500 uppercase tracking-wider">
              <span>Foundation Runtimes</span>
              <span className="text-zinc-600">Core Architecture</span>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 sm:gap-x-8 sm:gap-y-2.5">
              {foundationStacks.map((group) => (
                <div
                  key={group.category}
                  className="flex items-center gap-2 flex-wrap font-mono text-[11px]"
                >
                  <span className="text-zinc-500 font-medium text-[10px] uppercase tracking-wider shrink-0 select-none min-w-[65px]">
                    {group.category} /
                  </span>
                  <div className="flex items-center gap-1.5 flex-wrap">
                    {group.items.map((item) => (
                      <span
                        key={item}
                        className="px-2.5 py-0.5 rounded-[4px] border border-white/[0.07] bg-white/[0.025] text-zinc-300 text-[11px] font-mono select-none cursor-default"
                      >
                        {item}
                      </span>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </Reveal>

        {/* Frontier Press Wall (VIP Event Backboard with Stage Spotlight) */}
        <Reveal delay={0.25}>
          <div
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
            className="mt-4 sm:mt-5 rounded-2xl border border-white/10 bg-[#0c0c0f] overflow-hidden relative shadow-[inset_0_1px_0_0_rgba(255,255,255,0.08),0_20px_40px_-15px_rgba(0,0,0,0.5)] select-none"
          >
            {/* Dynamic Camera Flash / Stage Spotlight Beam */}
            <div
              className="pointer-events-none absolute -translate-x-1/2 -translate-y-1/2 rounded-full transition-opacity duration-300 z-[2]"
              style={{
                left: `${spotlightPos.x}px`,
                top: `${spotlightPos.y}px`,
                width: "420px",
                height: "420px",
                background:
                  "radial-gradient(circle, rgba(255, 255, 255, 0.12) 0%, rgba(255, 255, 255, 0.03) 45%, transparent 70%)",
                opacity: spotlightPos.opacity,
              }}
            />

            {/* Specular Grey Chrome Gradient Definition */}
            <svg
              className="absolute w-0 h-0 pointer-events-none"
              aria-hidden="true"
              focusable="false"
            >
              <defs>
                <linearGradient id="chrome-grad" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#FFFFFF" />
                  <stop offset="30%" stopColor="#E4E4E7" />
                  <stop offset="60%" stopColor="#A1A1AA" />
                  <stop offset="85%" stopColor="#D4D4D8" />
                  <stop offset="100%" stopColor="#71717A" />
                </linearGradient>
              </defs>
            </svg>

            {/* Header */}
            <div className="flex items-center justify-between px-4 py-2.5 sm:px-5 sm:py-3 border-b border-white/[0.06] bg-white/[0.015] font-mono text-[11px] relative z-[3] select-none">
              <span className="text-zinc-300 font-medium tracking-wide select-none">
                Frontier Tooling
              </span>
              <span className="text-zinc-500 text-[10px] tracking-widest font-mono lowercase select-none">
                et al.
              </span>
            </div>

            {/* Monolithic Seamed Grid — Zero Button Boxes */}
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 relative z-[3] select-none">
              {frontierTools.map((t) => (
                <div
                  key={t.name}
                  className="relative flex items-center justify-center gap-2.5 px-3 py-3.5 sm:py-4 border-r border-b border-white/[0.05] group transition-colors cursor-default select-none"
                >
                  {/* Architectural Corner Crosshair */}
                  <span className="absolute -bottom-2 -right-1 font-mono text-[8px] text-white/15 select-none pointer-events-none z-10">
                    +
                  </span>
                  <div className="w-4 h-4 shrink-0 transition-transform duration-200 group-hover:scale-110 pointer-events-none select-none">
                    {t.icon}
                  </div>
                  <span className="font-mono text-xs text-zinc-400 group-hover:text-zinc-100 transition-colors font-medium truncate select-none pointer-events-none">
                    {t.name}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </Reveal>
      </div>
    </section>
  );
}

